def load() -> pd.DataFrame:
    with open('data/wildfire/input/noaa_wildfires_monthly_stats.csv', 'r') as f:
        lines = f.readlines()

    data_start = None
    for i, line in enumerate(lines):
        if line.strip().startswith('Date'):
            data_start = i
            break

    if data_start is None:
        data_start = 0

    df = pd.read_csv('data/wildfire/input/noaa_wildfires_monthly_stats.csv', skiprows=data_start)
    return df

def process(compare_sources) -> pd.DataFrame:
    df = compare_sources.copy()

    avg_diff = df['fires_diff'].mean()
    result = round(avg_diff)

    return pd.DataFrame({
        'average_difference': [result],
        'raw_average': [avg_diff],
        'count_years': [len(df)]
    })
